import { Effect } from "effect"
import { Atom } from "effect/unstable/reactivity"
import { useAtomSet, useAtomValue } from "@effect/atom-react"
import { useId } from "react"

const healthRequest = Effect.tryPromise({
  try: async (signal) => {
    const response = await fetch("/api/health", { signal })
    if (!response.ok) throw new Error("Health check failed")
    return response.text()
  },
  catch: () => new Error("Service unavailable")
}).pipe(
  Effect.match({
    onFailure: () => "Service unavailable",
    onSuccess: (message) => message
  })
)

const healthAtoms = Atom.family((_id: string) => {
  const status = Atom.make("Not checked")
  const check = Atom.fn<void>()((_, get) =>
    Effect.gen(function*() {
      get.set(status, "Checking…")
      const message = yield* healthRequest
      get.set(status, message)
    })
  )
  return { status, check }
})

export function ServiceHealth() {
  const id = useId()
  const atoms = healthAtoms(id)
  const status = useAtomValue(atoms.status)
  const check = useAtomSet(atoms.check)

  return (
    <section aria-labelledby={id}>
      <h2 id={id}>Service health</h2>
      <output aria-live="polite">{status}</output>
      <button type="button" onClick={check}>
        Check connection
      </button>
    </section>
  )
}
